//  @ts-check

import base from '@repo/config-eslint/base.js';

/**
 * Everything under `src/` is ContractKit output, regenerated by `pnpm codegen`.
 *
 * `no-explicit-any` is off because the generator's bigint replacer and reviver are typed `any` and
 * a warning nobody can fix is a warning everybody learns to skip.
 *
 * @type {import("eslint").Linter.Config[]}
 */
export default [...base, { rules: { '@typescript-eslint/no-explicit-any': 'off' } }];
